// Product workspace body (production port of the frozen Phase 2 V2 workspace) — loaded on first use.
// nova.js owns identity, the shell (region / mobile dialog), focus and every CTA; this module only fetches and renders
// one Product's body: its listed items (D20), each with its own values, provenance and drawing. Nothing is shared or
// copied between items. Drawings are generated by the Publish Engine from sourced dimensions (05 §26).
const d = document;
// Documents attached to this item (its own links only), with the size shown before download
const sizeLabel = n => n < 1048576 ? Math.max(1, Math.round(n / 1024)) + ' KB' : (Math.round(n / 104857.6) / 10) + ' MB';
const $ = (s, c = d) => c.querySelector(s), $$ = (s, c = d) => [...c.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const ico = id => `<svg class="ico" aria-hidden="true"><use href="#${id}"/></svg>`;
const safeUrl = u => /^https?:\/\//.test(u || '') ? u : '';
let L = 'fa', FA = true;

export function fetchProduct(slug, signal) {
  return fetch(`/data/p/${encodeURIComponent(slug)}.json`, { signal }).then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); });
}

export function renderBody(main, p, a, T, mobile, onItem) {
  L = T.lang; FA = L === 'fa';
  const fill = (tpl, o) => tpl.replace(/\{(\w+)\}/g, (m, k) => (k in o ? o[k] : m));
  const iso = s => '⁦' + s + '⁩';
  const date = v => { try { return new Intl.DateTimeFormat(FA ? 'fa-IR' : 'en-GB', { dateStyle: 'medium' }).format(new Date(v + 'T12:00:00')); } catch { return v; } };
  const src = Object.fromEntries(p.sources.map(s => [s.key, s]));
  const items = p.items;

  if (!items.length) {
    main.innerHTML = `<div class="ws__body"><div class="empty">${ico('i-doc')}<span>${esc(fill(T.items_none, { code: iso(p.designation) }))}</span></div></div>`;
    return;
  }
  let current = Math.max(0, items.findIndex(i => i.slug === a.item));
  let tab = 0;

  const pv = r => r.st === 'ok' && r.src
    ? `<span class="pv" aria-hidden="true">${esc(r.src)}</span><span class="sr">${esc(T.st_val_ok)}, ${esc(T.col_src)} ${esc(r.src)}</span>`
    : `<span class="pv pv--pending">${esc(T.st_val_pending)}</span>`;
  const sourceLink = s => safeUrl(s.url)
    ? `<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener" lang="en" dir="ltr">${esc(s.label)} ${ico('i-ext')}</a>`
    : `<span lang="en" dir="ltr">${esc(s.label)}</span>`;
  const checked = s => s.checked ? `<span>${esc(fill(T.checked_t, { date: date(s.checked) }))}</span>` : '';

  const render = () => {
    const item = items[current];
    const values = item.values, core = values.filter(v => v.core);
    const keys = [...new Set(values.map(v => v.src).filter(Boolean))];
    const oneSource = keys.length === 1 && values.every(v => v.src === keys[0]);
    const valueRow = r => `<tr class="${r.st === 'ok' ? '' : 'is-pending'}"><th scope="row">${esc(r[L])}</th><td class="sym"><bdi dir="ltr">${esc(r.s)}</bdi></td>
      <td class="val"><bdi dir="ltr">${esc(r.v)}</bdi> <span class="u">${esc(r.u)}</span></td><td class="pvc">${r.src ? pv(r) : `${pv(r)} <span class="note">${esc(T.no_src)}</span>`}</td></tr>`;
    const table = values.length
      ? `<table class="spec prov"><caption>${esc(fill(T.item_values_h, { code: iso(item.designation) }))}</caption>
        <thead><tr><th scope="col">${esc(T.prop)}</th><th scope="col" class="sym">${esc(T.sym)}</th><th scope="col" class="val">${esc(T.value)}</th><th scope="col" class="pvc">${esc(T.col_src)}</th></tr></thead>
        <tbody>${values.map(valueRow).join('')}</tbody></table>`
      : `<p class="note">${esc(fill(T.no_values, { code: iso(item.designation) }))}</p>`;
    const legend = keys.length
      ? `<div class="prov-legend"><b>${esc(T.prov_h)}</b><ol>${keys.map(k => `<li><span class="pv" aria-hidden="true">${esc(k)}</span><span class="sr">${esc(T.col_src)} ${esc(k)}:</span>${sourceLink(src[k])}${checked(src[k])}</li>`).join('')}</ol>
        <p class="note">${esc(T.prov_note)}</p></div>` : '';
    // Overview: one scoped line when a single source covers every value of this item, the full legend otherwise
    const scoped = oneSource
      ? `<p class="src"><span>${esc(T.dims_h)} · ${esc(T.src)} <span class="pv" aria-hidden="true">${esc(keys[0])}</span>:</span>${sourceLink(src[keys[0]])}${checked(src[keys[0]])}</p>`
      : legend;
    const readout = core.length ? `<div class="readout" style="--n:${core.length}" role="group" aria-label="${esc(T.readout)}">${core.map(r =>
      `<div class="${r.st === 'ok' ? '' : 'is-pending'}"><small><bdi dir="ltr">${esc(r.s)}</bdi> · <span>${esc(r[L])}</span></small><b>${esc(r.v)}<i>${esc(r.u)}</i></b>${oneSource ? '' : pv(r)}</div>`).join('')}</div>` : '';
    const selector = items.length > 1
      ? `<div class="seg ws__items" role="group" aria-label="${esc(T.items_h)}"><span>${esc(T.items_h)}</span>${items.map((it, i) =>
        `<button type="button" data-item="${i}" aria-pressed="${i === current}"><bdi dir="ltr">${esc(it.designation)}</bdi></button>`).join('')}</div>` : '';
    const chips = (label, list) => list.length ? `<p class="src"><span>${esc(label)}:</span>${list.map(x => `<span class="chip" dir="ltr">${esc(x)}</span>`).join('')}</p>` : '';
    const tabs = T.tabs.map((l, i) => `<button class="tab" type="button" role="tab" id="wst-${i}" aria-controls="wsp-${i}" aria-selected="${i === tab}" tabindex="${i === tab ? 0 : -1}">${esc(l)}</button>`).join('');
    const about = p.description?.[L] ? `<div class="rc${L === 'en' ? ' en-prose' : ''}">${p.description[L]}</div>` : '';
    main.innerHTML = `${selector}${readout}
      <div class="tabs" role="tablist" aria-label="${esc(item.designation)}">${tabs}</div>
      <div class="ws__body">
        <div role="tabpanel" id="wsp-0" aria-labelledby="wst-0" tabindex="0"${tab === 0 ? '' : ' hidden'}>
          ${p.verified ? '' : `<div class="pendingbox" role="note"><b>${esc(T.st_pending)}</b><span>${esc(T.pending_p)}</span></div>`}
          ${item.drawing ? `<figure class="dwg">${item.drawing}<figcaption><span>${esc(item.designation)} · SECTION</span><span>NTS</span></figcaption></figure>` : ''}
          ${scoped}
          <p class="muted">${esc(p.family['def_' + L])}</p>
          ${about}
        </div>
        <div role="tabpanel" id="wsp-1" aria-labelledby="wst-1" tabindex="0"${tab === 1 ? '' : ' hidden'}>
          ${table}
          <h4 class="ws__sub">${esc(T.rating_h)}</h4><p class="note">${esc(T.rating_p)}</p>
          ${legend}
          ${chips(T.spellings_h, p.spellings)}
          <p class="note">${esc(T.dwg_cap)}</p>
        </div>
        <div role="tabpanel" id="wsp-2" aria-labelledby="wst-2" tabindex="0"${tab === 2 ? '' : ' hidden'}>${docsHtml(item, T)}</div>
      </div>`;

    const tabEls = $$('.tab', main);
    const select = (i, focus) => tabEls.forEach((t, k) => {
      const on = k === i;
      t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1;
      $('#wsp-' + k, main).hidden = !on;
      if (on) { tab = i; if (focus) t.focus(); }
    });
    tabEls.forEach((t, i) => t.addEventListener('click', () => select(i)));
    $('.tabs', main).addEventListener('keydown', e => {
      const i = tabEls.findIndex(t => t.getAttribute('aria-selected') === 'true');
      const step = { ArrowRight: FA ? -1 : 1, ArrowLeft: FA ? 1 : -1 }[e.key];
      if (step) { e.preventDefault(); select((i + step + tabEls.length) % tabEls.length, true); }
      if (e.key === 'Home') { e.preventDefault(); select(0, true); }
      if (e.key === 'End') { e.preventDefault(); select(tabEls.length - 1, true); }
    });
    $$('[data-item]', main).forEach(b => b.addEventListener('click', () => {
      current = +b.dataset.item;
      render();
      $(`[data-item="${current}"]`, main)?.focus();
      onItem?.(items[current]);
    }));
  };
  render();
  onItem?.(items[current]);
}

function docsHtml(item, T) {
  const lang = T.lang, docs = (item.documents || []).filter(x => x.lang === 'both' || x.lang === lang);
  if (!docs.length) return `<div class="empty">${ico('i-doc')}<span>${esc(T.docs_empty)}</span></div>`;
  return `<ul class="pp__docs-list">${docs.map(x => `<li><a href="${esc(x.url)}" download>${esc((lang === 'fa' ? x.title_fa : x.title_en) || x.name)}</a> <span class="note"><bdi dir="ltr">PDF · ${sizeLabel(x.bytes)}</bdi></span></li>`).join('')}</ul>`;
}
